function validate([grid, hits]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 200) return 'grid needs 1 to 200 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 200) return 'Each row needs 1 to 200 cells.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some((v) => v !== 0 && v !== 1)) return 'grid cells are 0 or 1.';
  }
  if (!Array.isArray(hits) || hits.length < 1 || hits.length > 40000) return 'hits needs 1 to 40000 cells.';
  const seen = new Set();
  for (const hit of hits) {
    if (!Array.isArray(hit) || hit.length !== 2) return 'Each hit is a [row, col] pair.';
    const [r, c] = hit;
    if (!Number.isInteger(r) || !Number.isInteger(c) || r < 0 || r >= grid.length || c < 0 || c >= n) return 'Each hit must be a cell inside the grid.';
    const key = r * n + c;
    if (seen.has(key)) return 'Each cell may be hit at most once.';
    seen.add(key);
  }
  return null;
}

