function hitBricks(grid, hits) {
  const rows = grid.length;
  const cols = grid[0].length;
  const roof = rows * cols;
  const parent = Array.from({ length: roof + 1 }, (_, i) => i);
  const size = new Array(roof + 1).fill(1);
  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };
  const union = (a, b) => {
    let rootA = find(a);
    let rootB = find(b);
    if (rootA === rootB) return;
    if (size[rootA] > size[rootB]) [rootA, rootB] = [rootB, rootA];
    parent[rootA] = rootB;
    size[rootB] += size[rootA];
  };
  const board = grid.map((row) => row.slice());
  for (const [r, c] of hits) {
    board[r][c] = 0;
  }
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const attach = (r, c) => {
    const id = r * cols + c;
    if (r === 0) union(id, roof);
    for (const [dr, dc] of directions) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] === 1) {
        union(id, nr * cols + nc);
      }
    }
  };
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (board[r][c] === 1) attach(r, c);
    }
  }
  const result = new Array(hits.length).fill(0);
  for (let i = hits.length - 1; i >= 0; i--) {
    const [r, c] = hits[i];
    if (grid[r][c] === 0) continue;
    const before = size[find(roof)];
    board[r][c] = 1;
    attach(r, c);
    const after = size[find(roof)];
    result[i] = Math.max(0, after - before - 1);
  }
  return result;
}

