function hitBricks(grid, hits) {
  // Simulate forwards: after every strike, flood-fill from the top row and drop whatever is not reached.
  const m = grid.length;
  const n = grid[0].length;
  const cells = grid.map((row) => row.slice());
  const dropUnstable = () => {
    const stable = cells.map((row) => row.map(() => false));
    const stack = [];
    for (let c = 0; c < n; c++) {
      if (cells[0][c] === 1) { stable[0][c] = true; stack.push([0, c]); }
    }
    while (stack.length) {
      const [r, c] = stack.pop();
      for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
        if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
        if (cells[nr][nc] !== 1 || stable[nr][nc]) continue;
        stable[nr][nc] = true;
        stack.push([nr, nc]);
      }
    }
    let dropped = 0;
    for (let r = 0; r < m; r++) {
      for (let c = 0; c < n; c++) {
        if (cells[r][c] === 1 && !stable[r][c]) { cells[r][c] = 0; dropped++; }
      }
    }
    return dropped;
  };
  dropUnstable(); // bricks that start unstable are never counted
  return hits.map(([r, c]) => {
    if (cells[r][c] === 0) return 0;
    cells[r][c] = 0;
    return dropUnstable();
  });
}

