function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const n = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const density = large ? 0.75 + rand() * 0.2 : 0.4 + rand() * 0.55;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  const total = m * n;
  const count = large ? Math.min(2000, total) : 1 + Math.floor(rand() * Math.min(total, 8));
  const order = Array.from({ length: total }, (_, i) => i);
  // Partial Fisher-Yates shuffle picks distinct cells to strike.
  for (let i = 0; i < count; i++) {
    const j = i + Math.floor(rand() * (total - i));
    [order[i], order[j]] = [order[j], order[i]];
  }
  const hits = order.slice(0, count).map((id) => [Math.floor(id / n), id % n]);
  return [grid, hits];
}
